phi2_lt = lm_phi2(Xtt, 12)
phi2_tl = lm_phi2(Xtt, 10)
phi2_ll = lm_phi2(Xtt, 5)

xlow = 0.02
Xtt_low = lm_martinelli_tt(xlow, rho_l, rho_g, mu_l, mu_g)
